/*
 * Kenneth | AXA Philippines
 * One coordinated script: carousel, scroll motion, portrait fallback, and the
 * opening loader. The contact card is generated by the server so unverified
 * title and organization details are never placed in a downloadable file.
 * Scroll animation is implemented once (the previous build ran two competing
 * implementations, which caused duplicated reveals and broken footer visibility).
 */
(() => {
  "use strict";

  const ready = (callback) => {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", callback, { once: true });
    } else {
      callback();
    }
  };

  const prefersReducedMotion = () =>
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function initPortraitFallback() {
    const photo = document.getElementById("portrait-photo");
    const placeholder = document.getElementById("photo-placeholder");
    if (!photo || !placeholder) return;

    const showPlaceholder = () => {
      photo.hidden = true;
      placeholder.style.display = "flex";
      placeholder.setAttribute("aria-hidden", "false");
    };

    photo.addEventListener("error", showPlaceholder);
    if (photo.complete && photo.naturalWidth === 0) showPlaceholder();
  }

  function initCarousel() {
    const viewport = document.getElementById("plans-showcase");
    const track = document.getElementById("plans-track");
    const dotsWrap = document.getElementById("plan-dots");
    const previous = document.getElementById("prev-plan");
    const next = document.getElementById("next-plan");
    const status = document.getElementById("plan-status");

    if (!viewport || !track || !dotsWrap) return;

    const slides = Array.from(track.querySelectorAll(".plan-card"));
    if (!slides.length) return;

    let current = 0;
    let startX = 0;
    let endX = 0;

    const slideName = (slide, index) => {
      const heading = slide.querySelector("h3");
      return heading ? heading.textContent.trim() : `Plan ${index + 1}`;
    };

    slides.forEach((slide, index) => {
      const dot = document.createElement("button");
      dot.type = "button";
      dot.className = "slide-dot";
      dot.setAttribute("aria-label", `Show plan ${index + 1} of ${slides.length}: ${slideName(slide, index)}`);
      dot.setAttribute("aria-controls", "plans-track");
      dot.addEventListener("click", () => showSlide(index));
      dotsWrap.appendChild(dot);
    });

    const dots = Array.from(dotsWrap.querySelectorAll(".slide-dot"));

    const setSlideInteractive = (slide, active) => {
      slide.setAttribute("aria-hidden", active ? "false" : "true");
      if ("inert" in slide) slide.inert = !active;

      // Fallback for browsers without inert support.
      slide.querySelectorAll("a, button, input, select, textarea, [tabindex]").forEach((element) => {
        if (active) {
          if (element.dataset.carouselTabindex !== undefined) {
            if (element.dataset.carouselTabindex === "") {
              element.removeAttribute("tabindex");
            } else {
              element.setAttribute("tabindex", element.dataset.carouselTabindex);
            }
            delete element.dataset.carouselTabindex;
          }
        } else if (!element.hasAttribute("tabindex")) {
          element.setAttribute("tabindex", "-1");
          element.dataset.carouselTabindex = "";
        }
      });
    };

    function showSlide(index, announce = true) {
      current = (index + slides.length) % slides.length;
      track.style.transform = `translateX(-${current * 100}%)`;

      dots.forEach((dot, dotIndex) => {
        dot.setAttribute("aria-current", dotIndex === current ? "true" : "false");
      });

      slides.forEach((slide, slideIndex) => {
        setSlideInteractive(slide, slideIndex === current);
      });

      if (status) {
        const announcement = `Plan ${current + 1} of ${slides.length}: ${slideName(slides[current], current)}`;
        status.textContent = announce ? announcement : "";
      }
    }

    previous?.addEventListener("click", () => showSlide(current - 1));
    next?.addEventListener("click", () => showSlide(current + 1));

    viewport.addEventListener("touchstart", (event) => {
      startX = event.changedTouches[0].clientX;
      endX = startX;
    }, { passive: true });

    viewport.addEventListener("touchend", (event) => {
      endX = event.changedTouches[0].clientX;
      const delta = endX - startX;
      if (Math.abs(delta) > 45) showSlide(current + (delta < 0 ? 1 : -1));
    }, { passive: true });

    viewport.addEventListener("touchcancel", () => {
      startX = 0;
      endX = 0;
    }, { passive: true });

    viewport.addEventListener("keydown", (event) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        showSlide(current - 1);
      } else if (event.key === "ArrowRight") {
        event.preventDefault();
        showSlide(current + 1);
      } else if (event.key === "Home") {
        event.preventDefault();
        showSlide(0);
      } else if (event.key === "End") {
        event.preventDefault();
        showSlide(slides.length - 1);
      }
    });

    showSlide(0, false);
  }

  function initMotion() {
    const progress = document.getElementById("scroll-progress-bar");
    const updateProgress = () => {
      if (!progress) return;
      const max = document.documentElement.scrollHeight - window.innerHeight;
      const amount = max > 0 ? (window.scrollY / max) * 100 : 0;
      progress.style.width = `${Math.min(100, Math.max(0, amount))}%`;
    };
    window.addEventListener("scroll", updateProgress, { passive: true });
    window.addEventListener("resize", updateProgress, { passive: true });
    updateProgress();

    if (prefersReducedMotion()) return;

    const revealSelectors = [
      ".hero-copy > *", ".portrait-stage", ".profile-name > *",
      ".section-heading > *", ".category-card", ".plans-showcase",
      ".showcase-controls", ".showcase-hint", ".disclaimer",
      ".recruit-section > *", ".contact-button", ".save-contact-wrap"
    ];
    const revealItems = Array.from(document.querySelectorAll(revealSelectors.join(",")));

    revealItems.forEach((element) => {
      element.setAttribute("data-reveal", "");
      const siblingIndex = Array.from(element.parentElement.children).indexOf(element);
      element.style.setProperty("--reveal-delay", `${Math.min(siblingIndex * 85, 425)}ms`);
    });

    // Split headings once. The previous implementation split the same headings twice,
    // nesting character spans and causing the broken/duplicated animation.
    // Character-level splitting is skipped on narrow screens so long headings can
    // wrap naturally instead of becoming individually unbreakable inline blocks.
    const canSplitHeadings = !window.matchMedia("(max-width: 700px)").matches;
    if (canSplitHeadings) document.querySelectorAll(".hero h1, .profile-name h2, .section-heading h2, .recruit-section h2").forEach((heading) => {
      if (heading.dataset.motionSplit === "true") return;
      heading.dataset.motionSplit = "true";

      const originalText = (heading.innerText || heading.textContent).replace(/\s+/g, " ").trim();
      const walker = document.createTreeWalker(heading, NodeFilter.SHOW_TEXT);
      const textNodes = [];
      while (walker.nextNode()) textNodes.push(walker.currentNode);

      let letterIndex = 0;
      textNodes.forEach((node) => {
        const fragment = document.createDocumentFragment();
        // Wrap each word so character animations never break a word mid-way.
        node.nodeValue.split(/(\s+)/).forEach((token) => {
          if (!token) return;
          if (/^\s+$/.test(token)) {
            fragment.appendChild(document.createTextNode(" "));
            return;
          }
          const word = document.createElement("span");
          word.className = "motion-word";
          Array.from(token).forEach((character) => {
            const span = document.createElement("span");
            span.setAttribute("data-letter", "");
            span.setAttribute("aria-hidden", "true");
            span.textContent = character;
            span.style.setProperty("--letter-delay", `${Math.min(letterIndex * 22, 650)}ms`);
            word.appendChild(span);
            letterIndex += 1;
          });
          fragment.appendChild(word);
        });
        node.parentNode.replaceChild(fragment, node);
      });

      heading.setAttribute("aria-label", originalText);
    });

    if (!("IntersectionObserver" in window)) {
      revealItems.forEach((element) => element.classList.add("is-visible"));
      return;
    }

    document.body.classList.add("js-motion");

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-visible");
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.13, rootMargin: "0px 0px -35px 0px" });

    revealItems.forEach((element) => observer.observe(element));

    const motionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    const revealAll = () => {
      document.body.classList.remove("js-motion");
      revealItems.forEach((element) => element.classList.add("is-visible"));
      observer.disconnect();
    };
    if (typeof motionQuery.addEventListener === "function") {
      motionQuery.addEventListener("change", (event) => {
        if (event.matches) revealAll();
      });
    }
  }

  function scrollToCurrentHash() {
    if (!window.location.hash) return;
    const id = decodeURIComponent(window.location.hash.slice(1));
    const target = document.getElementById(id);
    if (target) target.scrollIntoView({ block: "start", behavior: "auto" });
  }

  function initLoader() {
    const loader = document.getElementById("axa-loader");
    if (!loader) return;

    document.body.classList.add("loader-active");

    const hide = () => {
      if (loader.classList.contains("is-leaving")) return;
      loader.classList.add("is-leaving");
      document.body.classList.remove("loader-active");
      window.setTimeout(() => {
        loader.remove();
        // Deep links must survive the loader. Never force the page back to the top
        // when a fragment was requested.
        if (window.location.hash) {
          scrollToCurrentHash();
        } else {
          window.scrollTo({ top: 0, left: 0, behavior: "auto" });
        }
      }, 750);
    };

    const minDuration = prefersReducedMotion() ? 250 : 1750;
    const started = performance.now();
    const finishAt = () => {
      const remaining = Math.max(0, minDuration - (performance.now() - started));
      window.setTimeout(hide, remaining);
    };

    if (document.readyState === "complete") finishAt();
    else window.addEventListener("load", finishAt, { once: true });

    // Fail-safe if an external resource never completes.
    window.setTimeout(hide, 2600);
  }

  ready(() => {
    initPortraitFallback();
    initCarousel();
    initMotion();
    initLoader();
  });
})();
